const prom = String($env.PROMETHEUS_QUERY_URL || '').trim();
const b = $input.first().json.body ?? $input.first().json;
const query = String(b.promql || 'up');
let metrics = { skipped: true, reason: 'PROMETHEUS_QUERY_URL no configurada (ej. http://prometheus:9090/api/v1/query)' };
if (prom) {
  const u = new URL(prom);
  u.searchParams.set('query', query);
  const r = await fetch(u.toString(), { method: 'GET' });
  const t = await r.text();
  let parsed;
  try { parsed = JSON.parse(t); } catch { parsed = { raw: t }; }
  metrics = { http_status: r.status, promql: query, response: parsed };
}
return [{ json: { success: true, metrics, kubernetes_hint: 'HPA/replicas vía API del clúster no incluido: usar credenciales mínimas y workflow aparte.' } }];
